<script setup>
import {ref,onMounted,onBeforeUnmount} from 'vue'
import ScreenChart from '@/ScreenChart.vue'
import ScreenDrawer from '@/ScreenDrawer.vue'
import {useScreenState} from '@/screen-state.js'
const state=useScreenState()
const tickerIndex=ref(0);let tickerTimer
onMounted(()=>{tickerTimer=setInterval(()=>tickerIndex.value++,5000)});onBeforeUnmount(()=>clearInterval(tickerTimer))
const {mode,view,data,error,loading,notice,mapStatus,mapEl,drawer,metric,detail,page,compareIds,comparison,eventDetail,drill,selected,hover,openEvidence,fullscreen,filter,visible,sections,d,supply,dynamic,charts,districts,label,fmt,list,loginOpen,loginBusy,loginError,username,password,leftOpen,rightOpen,managementUrl,login,refresh,demands,loadDemands,openEvent,compare,selectMap,selectChart,setView,reset,simulation,yearcards,category,enterprise,regions,communities,monthly,hourly,duration,reasons}=state
</script>
<template>
<div class="screen"><div ref="mapEl" class="map"></div><div class="top-bg"></div><div class="bottom-bg"></div>
<header><div class="clock">{{ new Date().toLocaleDateString('zh-CN') }}<small> {{ mode==='simulation'?'模拟演示':'真实数据' }}</small></div><h1>宜昌市供气供水行业诉求一张图</h1><div><button @click="loginOpen=true">登录</button> <button @click="simulation">切换{{mode==='real'?'模拟演示':'真实数据'}}</button></div></header>
<div class="nav"><button v-for="v in [['gas','供气服务'],['water','供水服务'],['dynamic','诉求动态']]" :class="{active:view===v[0]}" @click="setView(v[0])">{{v[1]}}</button></div>
<div class="filters"><label>开始 <input type="date" v-model="filter.from"></label><label>结束 <input type="date" v-model="filter.to"></label><select v-model="filter.districtCode"><option value="">全部区划</option><option v-for="(name,code) in districts" :value="code">{{name}}</option></select><select v-model="filter.enterpriseCode"><option value="">全部企业</option><option v-for="x in supply.enterpriseRates" :value="x.id">{{x.name||x.id}}</option></select><select v-model="filter.adminGridCode"><option value="">全部网格</option><option v-for="x in sections.grids" :value="x.id">{{x.name}}</option></select><select v-model="filter.communityCode"><option value="">全部小区</option><option v-for="x in sections.communities" :value="x.id">{{x.name}}</option></select><select v-model="filter.categoryCode"><option value="">全部分类</option><option v-for="x in charts.category" :value="x.code">{{label(x.code)}}</option></select><button @click="refresh">查询</button><button @click="reset">重置</button></div>
<div class="status" v-if="error||notice||loading">{{loading?'正在加载…':error||notice}}</div>
<button class="side-toggle left-toggle" @click="leftOpen=!leftOpen">{{leftOpen?'‹':'›'}}</button><button class="side-toggle right-toggle" @click="rightOpen=!rightOpen">{{rightOpen?'›':'‹'}}</button><div class="left side" v-show="leftOpen"><section class="card"><h2>诉求总览 <small>{{d.periodAnchor||'截至所选日期 —'}}</small></h2><div class="metrics"><button v-for="[key,title] in yearcards" @click="demands(key)"><strong>{{fmt(d.periods?.[key]?.count)}}</strong><span>{{title}}</span><small>{{d.periods?.[key]?.from||'—'}} 至 {{d.periods?.[key]?.to||'—'}}</small></button></div><p class="muted">所选窗口 {{d.window?.from||'—'}} 至 {{d.window?.to||'—'}} · {{fmt(d.summary?.total)}} 件 <button @click="demands()">查看明细 ›</button></p></section>
<section class="card"><h2>{{view==='dynamic'?'评价情况':'问题类型分布'}}</h2><template v-if="view==='dynamic'"><div class="evaluation"><strong>{{fmt(dynamic.evaluation?.percent)}}<small v-if="dynamic.evaluation?.percent!=null">%</small></strong><span>有效评价满意率</span></div><p class="muted">满意 {{fmt(dynamic.evaluation?.satisfiedCount)}} · 不满意 {{fmt(dynamic.evaluation?.unsatisfiedCount)}} · 未评价 {{fmt(dynamic.evaluation?.unevaluatedCount)}}</p><p v-if="dynamic.evaluation?.percent==null" class="muted">{{reasons}}</p></template><ScreenChart v-else :items="category" @select="selectChart('category',$event)"/></section>
<section class="card"><h2>{{view==='dynamic'?'办理时长分布':'企业每万户诉求量'}}</h2><ScreenChart :items="view==='dynamic'?duration:enterprise" @select="view!=='dynamic'&&selectChart('enterprise',$event)"/><p class="muted" v-if="view!=='dynamic'">{{d.supply?.reason}} · 点击企业筛选；不可计算项请在专题中查看原因</p></section></div>
<div class="right side" v-show="rightOpen"><section class="card"><h2>{{view==='dynamic'?'高峰时段':'月度变化趋势'}}</h2><ScreenChart :kind="'line'" :items="view==='dynamic'?hourly:monthly"/></section><section class="card"><h2>{{view==='dynamic'?'不满意行业构成':'区域分布'}}</h2><ScreenChart :kind="view==='dynamic'?'bar':'pie'" :items="view==='dynamic'?list(dynamic.unsatisfiedBusiness,'businessType'):regions" @select="view!=='dynamic'&&selectChart('district',$event)"/></section><section class="card"><h2>{{view==='dynamic'?'周变化趋势':'高频诉求小区'}}</h2><ScreenChart :kind="view==='dynamic'?'line':'bar'" :items="view==='dynamic'?list(dynamic.weekly,'date'):communities" @select="view!=='dynamic'&&selectChart('community',$event)"/></section></div>
<div class="map-info"><b>地图与图层</b><p>{{mapStatus}}</p><p v-if="mode==='simulation'" class="simulation-label">模拟网格/模拟坐标，非正式边界</p><p>{{d.spatial?.reason}}</p><p v-if="hover">{{hover.name}} · {{fmt(hover.count)}} 件<br>{{hover.source}}</p><p v-if="selected">当前选中：{{label(selected)}} <button @click="reset">清除</button></p><details><summary>图层开关与图例</summary><label v-for="(name,key) in {grids:'网格',communities:'小区','planned-water':'计划停水','planned-gas':'计划停气','emergency-water':'突发停水','emergency-gas':'突发停气',construction:'施工','pipe-water':'供水管线','pipe-gas':'燃气管线'}"><input type="checkbox" v-model="visible[key]">{{name}}</label><p>计划水 ● 青　计划气 ● 橙<br>突发水 ● 红　突发气 ● 紫<br>施工 ● 黄　供水线 — 青　燃气线 — 橙</p><p>热力：{{d.heat?.reason||'未提供'}}<br>{{d.window?.from}} 至 {{d.window?.to}} · {{fmt(d.heat?.data?.days)}} 天<br>政策 {{d.heat?.data?.policyId||'未提供'}} · {{d.heat?.data?.ruleVersion||'版本未提供'}}</p><p v-if="d.heat?.data?.thresholds">阈值＝天数×系数；等于阈值归低档，零值绿色，超顶红色。</p><div v-for="(color,i) in ['#48c978','#42a9eb','#f0d34a','#f49b3f','#ec5151']"><i class="swatch" :style="{background:color}"></i>{{['绿','蓝','黄','橙','红'][i]}}：阈值 {{fmt(d.heat?.data?.thresholds?.[i])}} / 系数 {{d.heat?.data?.coefficients?.[i]||'不可计算'}}</div></details></div>
<div class="map-actions"><button @click="reset">地图复位</button><button @click="fullscreen">全屏</button><button @click="drawer='compare'">网格对比</button><button @click="drawer='warnings'">数据预警</button><button @click="drawer='research'">冬夏研判</button><button @click="drawer='events'">停供与施工</button><button @click="drawer='analysis'">更多分析</button></div>
<div class="ticker">往年同期 TOP 3（{{d.top3?.data?.from||'—'}} 至 {{d.top3?.data?.to||'—'}}）：<button v-if="d.top3?.data?.items?.length" @click="openEvidence({type:'top3',code:d.top3.data.items[tickerIndex % d.top3.data.items.length].code})">{{d.top3.data.items[tickerIndex % d.top3.data.items.length].code}} {{d.top3.data.items[tickerIndex % d.top3.data.items.length].count}} 件　查看证据 ›</button><span v-else>{{d.top3?.reason||'暂无数据'}}</span><button v-if="d.top3?.data?.items?.length>1" @click="tickerIndex++">下一条</button></div>
<ScreenDrawer :state="state" /><div v-if="loginOpen" class="shade"><form class="login" @submit.prevent="login"><h2>登录诉求平台</h2><p>使用管理平台授权账号</p><input v-model="username" placeholder="用户名" autocomplete="username" required><input v-model="password" placeholder="密码" type="password" autocomplete="current-password" required><p v-if="loginError">{{loginError}}</p><button :disabled="loginBusy">{{loginBusy?'登录中…':'登录'}}</button> <button type="button" @click="loginOpen=false;password=''">取消</button><p><a v-if="managementUrl" :href="managementUrl">前往管理后台 / 修改密码</a><span v-else>管理后台入口未配置</span></p></form></div></div>
</template>
<style>
.screen{position:relative;width:100vw;height:100vh;overflow:hidden;background:#061d1e;color:#d6f6ef;font-family:Arial,'Microsoft YaHei',sans-serif;font-size:14px}.map{position:absolute;inset:0;background:#082525 url('@/assets/image/map_fallback.png') center/cover}.top-bg,.bottom-bg{position:absolute;pointer-events:none;width:100%;background-size:100% 100%}.top-bg{height:18%;top:0;background-image:url('@/assets/image/top_bg.png')}.bottom-bg{height:15%;bottom:0;background-image:url('@/assets/image/bottom_bg.png')}header{position:absolute;top:0;left:2%;right:2%;height:8%;display:flex;align-items:flex-start;justify-content:space-between;z-index:2}h1{font:36px YouSheBiaoTiHei,sans-serif;letter-spacing:4px;color:white;margin:12px 0;text-shadow:0 2px 8px #7cdecf}.clock{padding-top:22px;font-size:17px}.clock small{color:#70d8c2;margin-left:10px}button,select,input{font:inherit;color:#d5f8ef;background:#0c3632;border:1px solid #347d72;border-radius:3px;padding:6px 10px}button{cursor:pointer}button:hover,.active{background:#1b7466;border-color:#86fbe7;color:white}header button{margin-top:15px}.nav{position:absolute;top:9%;left:35%;width:30%;display:flex;justify-content:center;gap:8px}.nav button{width:125px}.filters{position:absolute;z-index:3;top:15%;left:23%;right:23%;display:flex;justify-content:center;flex-wrap:wrap;gap:4px}.filters input,.filters select{max-width:120px;padding:4px;font-size:12px}.filters label{font-size:12px;white-space:nowrap}.filters button{padding:4px 10px}.side{position:absolute;top:9%;bottom:2%;width:21%;display:flex;flex-direction:column;gap:1%;z-index:2}.left{left:2%}.right{right:2%}.card{height:33%;min-height:0;display:flex;flex-direction:column;background:linear-gradient(100deg,rgba(5,35,33,.94),rgba(3,24,25,.78));border:1px solid rgba(51,139,124,.5);box-shadow:inset 0 0 24px #0b494044;padding:10px 14px}.card h2,.drawer h2{font:22px YouSheBiaoTiHei,sans-serif;letter-spacing:2px;margin:0 0 8px;padding:0 0 8px 14px;color:#e5fff8;background:url('@/assets/image/title_bg.png') left center/100% 100% no-repeat}.card h2 small{font:11px Arial;color:#97cbc0;letter-spacing:0}.chart{flex:1}.metrics{display:grid;grid-template-columns:repeat(4,1fr);gap:5px;flex:1}.metrics button{display:flex;flex-direction:column;align-items:center;justify-content:center;padding:3px;background:#0c413b88;border-color:#2b7064}.metrics strong,.evaluation strong{font:28px YouSheBiaoTiHei;color:#8fffe8}.metrics small{font-size:9px;color:#8ab9b0}.muted{color:#8fbcb4;font-size:11px;margin:6px 0}.muted button{font-size:11px;padding:2px}.evaluation{display:flex;flex:1;align-items:center;justify-content:center;gap:12px}.map-info{position:absolute;left:24%;bottom:13%;z-index:2;width:205px;padding:10px;background:#062e2be8;border:1px solid #347d72;font-size:12px}.map-info p{margin:6px 0;color:#a8d8ce}.map-info label{display:inline-block;margin-right:8px}.map-info input{vertical-align:middle}.map-actions{position:absolute;bottom:9%;left:35%;right:24%;display:flex;gap:5px;justify-content:center}.map-actions button{white-space:nowrap}.ticker{position:absolute;bottom:3%;left:25%;right:25%;text-align:center;color:#a2eee0;background:#072d2cbd;padding:8px;white-space:nowrap;overflow:hidden}.status{position:absolute;z-index:4;top:23%;left:30%;right:30%;text-align:center;background:#513b18ed;padding:8px}.shade{position:absolute;z-index:20;inset:0;background:#0008;display:flex;justify-content:flex-end}.drawer{width:min(700px,65vw);height:100%;overflow:auto;box-sizing:border-box;background:#072827;border-left:1px solid #59a998;padding:24px;color:#cceee7}.drawer-head{display:flex;justify-content:space-between;align-items:center;position:sticky;top:0;background:#072827}.drawer h3{color:#8df1db;margin-top:28px}.drawer select{display:block;width:100%;margin:10px 0}.drawer pre{white-space:pre-wrap;word-break:break-all;color:#a6d9cc;line-height:1.6}.row{display:flex;width:100%;justify-content:space-between;text-align:left;margin:5px 0;padding:10px;border-bottom:1px solid #285a51}.drawer p{color:#acd6ce}.drawer button:disabled{opacity:.4}@media(max-width:1400px){h1{font-size:27px}.side{width:23%}.left{left:1%}.right{right:1%}.filters{left:25%;right:25%}.card{padding:7px}.metrics strong{font-size:21px}.map-info{left:25%}}
.swatch{display:inline-block;width:10px;height:10px;margin-right:6px}.simulation-label{color:#ffd67c!important;font-weight:bold}.map-info details{max-height:29vh;overflow:auto}.ticker button{padding:2px 7px}.side-toggle{position:absolute;top:48%;z-index:5;padding:8px}.left-toggle{left:23%}.right-toggle{right:23%}.analysis-chart{height:180px}.compare-shade{pointer-events:none;background:transparent}.compare-shade .drawer{pointer-events:auto}.login{margin:auto;width:320px;background:#072827;border:1px solid #59a998;padding:25px;display:flex;flex-direction:column;gap:10px}.login a{color:#8fffe8}
</style>
